import sys

def main():
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    s = input[1]
    countV = [0]
    countK = [0]
    countOther = [0]
    positionsV = [[0] for _ in range(n)]
    positionsK = [[0] for _ in range(n)]
    positionsO = [[0] for _ in range(n)]
    vCount = 0
    kCount = 0
    oCount = 0
    for i in range(n):
        c = s[i]
        if c == 'V':
            positionsV[vCount][0] = i
            vCount += 1
        elif c == 'K':
            positionsK[kCount][0] = i
            kCount += 1
        else:
            positionsO[oCount][0] = i
            oCount += 1
    import math
    dp = [[[[math.inf for _ in range(2)] for _ in range(oCount + 1)] for _ in range(kCount + 1)] for _ in range(vCount + 1)]
    p = [[[0 for _ in range(n)] for _ in range(3)] for _ in range(3)]
    for x in range(3):
        for y in range(3):
            if x != y:
                for i in range(vCount):
                    for j in range(kCount):
                        if (x == 0 and y == 1 and positionsK[j][0] < positionsV[i][0]) or \
                           (x == 0 and y == 2 and positionsO[j][0] < positionsV[i][0]) or \
                           (x == 1 and y == 0 and positionsV[j][0] < positionsK[i][0]) or \
                           (x == 1 and y == 2 and positionsO[j][0] < positionsK[i][0]) or \
                           (x == 2 and y == 0 and positionsV[j][0] < positionsO[i][0]) or \
                           (x == 2 and y == 1 and positionsK[j][0] < positionsO[i][0]):
                            p[x][y][i] += 1
    dp[0][0][0][1] = 0
    for i in range(vCount + 1):
        for j in range(kCount + 1):
            for k in range(oCount + 1):
                for q in range(2):
                    if dp[i][j][k][q] != math.inf:
                        if i < vCount:
                            val = dp[i][j][k][q] + max(p[0][1][i] - j, 0) + max(p[0][2][i] - k, 0)
                            if val < dp[i + 1][j][k][0]:
                                dp[i + 1][j][k][0] = val
                        if j < kCount and q == 1:
                            val = dp[i][j][k][q] + max(p[1][0][j] - i, 0) + max(p[1][2][j] - k, 0)
                            if val < dp[i][j + 1][k][1]:
                                dp[i][j + 1][k][1] = val
                        if k < oCount:
                            val = dp[i][j][k][q] + max(p[2][0][k] - i, 0) + max(p[2][1][k] - j, 0)
                            if val < dp[i][j][k + 1][1]:
                                dp[i][j][k + 1][1] = val
    print(min(dp[vCount][kCount][oCount][0], dp[vCount][kCount][oCount][1]))

if __name__ == "__main__":
    main()

